import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"Utils API","link":"/api/Utils-API/Utils-API"},{"text":"平台信息获取","link":"/api/Utils-API/platform_info/platform_info"},{"text":"PlatformAscendC","link":"/api/Utils-API/platform_info/PlatformAscendC/PlatformAscendC"},{"text":"PlatformAscendC简介","link":"/api/Utils-API/platform_info/PlatformAscendC/PlatformAscendC_intro"}]},"headers":[],"relativePath":"api/Utils-API/platform_info/PlatformAscendC/PlatformAscendC_intro.md","filePath":"api/Utils-API/platform_info/PlatformAscendC/PlatformAscendC_intro.md","outlineHeaders":[{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"},{"level":2,"title":"常见使用方式","slug":"常见使用方式","link":"#常见使用方式"},{"level":3,"title":"自定义算子工程","slug":"自定义算子工程","link":"#自定义算子工程"},{"level":3,"title":"Kernel直调","slug":"Kernel直调","link":"#Kernel直调"}],"lastUpdated":1788503810000}'),c={name:"api/Utils-API/platform_info/PlatformAscendC/PlatformAscendC_intro.md"};function t(e,s,o,i,r,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>PlatformAscendC简介<span id="ZH-CN_TOPIC_0000002224684138"></span></h1><p>在实现Host侧的Tiling函数时，可能需要获取一些硬件平台的信息，来支撑Tiling的计算，比如获取硬件平台的核数等信息。PlatformAscendC类提供获取这些平台信息的功能。</p><h2 id="需要包含的头文件">需要包含的头文件<span id="section78885814919"></span><a class="header-anchor" href="#需要包含的头文件">​</a></h2><p>使用该功能需要包含&quot;tiling/platform/platform_ascendc.h&quot;头文件。样例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;tiling/platform/platform_ascendc.h&quot;
</code></pre></div><h2 id="常见使用方式">常见使用方式<a class="header-anchor" href="#常见使用方式">​</a></h2><h3 id="自定义算子工程">自定义算子工程<a class="header-anchor" href="#自定义算子工程">​</a></h3><p>自定义算子工程通常在Tiling函数中使用。框架通过<code>gert::TilingContext</code>传入平台信息，可据此构造<code>PlatformAscendC</code>对象后调用平台信息接口。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">ge</span><span class="o">::</span><span class="n">graphStatus</span><span class="w"> </span><span class="nf">TilingXXX</span><span class="p">(</span><span class="n">gert</span><span class="o">::</span><span class="n">TilingContext</span><span class="o">*</span><span class="w"> </span><span class="n">context</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">ascendcPlatform</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">platform_ascendc</span><span class="o">::</span><span class="n">PlatformAscendC</span><span class="p">(</span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetPlatformInfo</span><span class="p">());</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">coreNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ascendcPlatform</span><span class="p">.</span><span class="n">GetCoreNum</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// ... 根据核数自行设计Tiling策略</span>
<span class="w">    </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">SetSimdNumBlocks</span><span class="p">(</span><span class="n">coreNum</span><span class="p">);</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">ret</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div><h3 id="Kernel直调">Kernel直调<a class="header-anchor" href="#Kernel直调">​</a></h3><p>Kernel直调不通过<code>gert::TilingContext</code>获取平台信息，可通过<a href="../PlatformAscendCManager.html">PlatformAscendCManager</a>直接获取<code>PlatformAscendC</code>指针后调用相同的平台信息接口。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">void</span><span class="w"> </span><span class="nf">GetInfoFun</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="o">*</span><span class="w"> </span><span class="n">ascendcPlatform</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">platform_ascendc</span><span class="o">::</span><span class="n">PlatformAscendCManager</span><span class="o">::</span><span class="n">GetInstance</span><span class="p">();</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ascendcPlatform</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">coreNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ascendcPlatform</span><span class="o">-&gt;</span><span class="n">GetCoreNum</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// ... 根据核数自行设计切分策略</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const m=a(c,[["render",t]]);export{f as __pageData,m as default};
